def sha(raw):return hashlib.sha256(raw).hexdigest()
def canonical(value):return json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode('utf-8')
def need(ok,label):
    if not ok:raise ValueError('STAGE_A_'+label)

class InitialDeadline(KeyboardInterrupt):pass
@contextlib.contextmanager
def initial_bounded():
    need(signal.getitimer(signal.ITIMER_REAL)==(0.0,0.0),'EXISTING_ALARM')
    previous=signal.getsignal(signal.SIGALRM);primary=None
    def expired(*unused):raise InitialDeadline()
    signal.signal(signal.SIGALRM,expired)
    try:
        signal.setitimer(signal.ITIMER_REAL,60,1);yield
    except BaseException as error:primary=error;raise
    finally:
        failed=False
        try:signal.setitimer(signal.ITIMER_REAL,0)
        except BaseException:failed=True
        try:signal.signal(signal.SIGALRM,previous)
        except BaseException:failed=True
        if failed:
            if primary is not None:primary.diagnostic_cleanup_failed=True
            else:
                failure=ValueError('STAGE_A_TIMER_CLEANUP');failure.diagnostic_cleanup_failed=True;raise failure

def unpack(row):
    need(type(row) is dict and set(row)=={'sha256','bytes','zlib_base64'},'EMBEDDED_ROW')
    need(type(row['bytes']) is int and 0<row['bytes']<=262144,'EMBEDDED_BOUND')
    packed=base64.b64decode(row['zlib_base64'],validate=True);need(len(packed)<=131072,'PACKED_BOUND')
    dec=zlib.decompressobj();raw=dec.decompress(packed,row['bytes']+1)
    need(len(raw)==row['bytes'] and dec.eof and not dec.unused_data and not dec.unconsumed_tail and sha(raw)==row['sha256'],'EMBEDDED_PIN')
    return raw

def load_module(raw,name):
    module=types.ModuleType(name);module.__file__='<'+name+'>'
    exec(compile(raw,module.__file__,'exec',dont_inherit=True),module.__dict__)
    return module

def load_exporter():
    raw=unpack(EMBEDDED_EXPORTER);need(sha(raw)=='a436d97072bf0062a94f9ccbd030aef1a08214f12f74645efd12d89d9f464815','EXPORTER_PIN')
    return load_module(raw,'stage_a_reviewed_exporter')

def register_source(d,label,path,raw):
    d.remember_source(label,path,raw)
    for node in ast.walk(ast.parse(raw)):
        if isinstance(node,ast.Str) and type(node.s) is str and re.fullmatch('[A-Z][A-Z0-9_]{0,127}',node.s):
            for prefix in ('STAGE_A_','SAVED_A2_','SAVED_AUTHORITY_'):
                if len(prefix+node.s)<=160:d.SAFE_CODES.add(prefix+node.s)

def load_mapper(d):
    raw=unpack(EMBEDDED_MAPPER);register_source(d,'A2_MAPPER','<stage_a_saved_mapper>',raw)
    return load_module(raw,'stage_a_saved_mapper')

def authenticate_observer(kit,d):
    need(kit.manifest['kit_source_commit']==d.SOURCE and len(kit.cache)==252,'KIT_SOURCE_SCOPE')
    for name,pin in OBSERVER_SOURCES.items():need(sha(kit.cache['helpers/'+name])==pin,'OBSERVER_SOURCE_PIN')
    for name,raw in kit.cache.items():
        if name.endswith('.py'):register_source(d,'KIT:'+name,d.KIT+'/'+name,raw)

def read_complete_pair(entry,d,observation,diagnostic):
    # The same fixed two protected paths as the reviewed reader, no new scope.
    with entry.DescriptorTree(d.BASE) as tree:
        raw=tree.read(d.FILE,64*1024*1024,private=True)
        receipt_raw=tree.read(d.RECEIPT,16384,private=True)
        tree.recheck()
    need(sha(raw)==d.OBS_SHA and sha(receipt_raw)==d.RECEIPT_SHA,'COMPLETE_RAW_PINS')
    need(canonical(entry.decode(raw))==canonical(observation) and canonical(entry.decode(receipt_raw))==canonical(diagnostic),'COMPLETE_RAW_OBJECTS')
    need(sha(canonical(observation))==OBS_CANONICAL_SHA,'COMPLETE_CANONICAL_PIN')
    return raw,receipt_raw

def retained_body():
    raw=base64.b64decode(ORIGINAL_BODY_BASE64,validate=True)
    need(len(raw)==BODY_BYTES and sha(raw)==BODY_SHA,'ORIGINAL_BODY_BYTES')
    value=json.loads(raw.decode('utf-8'));need(canonical(value)==raw,'ORIGINAL_BODY_CANONICAL')
    return raw,value

def verify_projection(packet,d):
    need(packet['observation_file_sha256']==d.OBS_SHA and packet['diagnostic_receipt_sha256']==d.RECEIPT_SHA,'PROJECTION_INPUT_PINS')
    need(packet['observation_full_canonical_sha256']==OBS_CANONICAL_SHA and packet['nonce']==d.NONCE and packet['observation_id']==d.OBSERVATION_ID,'PROJECTION_ATTEMPT')
    need(packet['bindings']==EXPECTED_BINDINGS,'PROJECTION_BINDINGS')
    for name,pin in EXPECTED_SEVEN.items():
        actual=packet[name] if name in ('topology_sha256','expected_review_body_sha256') else packet['bindings'][name]
        need(actual==pin,'PROJECTION_SEVEN_HASHES')
    raw,body=retained_body();need(canonical(packet['unsigned_expected_review_body'])==raw,'ORIGINAL_BODY_EQUALITY')
    need(body['production_resume_authorized'] is False and body['schema']==2,'BODY_SCOPE')
    return {name:pin for name,pin in sorted(EXPECTED_SEVEN.items())}

def ancillary_status(observation):
    result=[]
    allowed=frozenset(('COMPLETE_UNREVIEWED','MEASURED_UNREVIEWED','UNKNOWN','UNSUPPORTED',
        'HOLD','NOT_RUN','MISSING','ERROR','INCOMPLETE','COMPLETE','PASS','PASS_OBSERVED','NOT_VERIFIED','NOT_INFERRED','PENDING'))
    for index,name in enumerate(('probe_metadata','unit_metadata','source_review_inputs','openclaw_profile')):
        value=observation.get(name) if type(observation) is dict else None
        row={'block_index':index,'present':value is not None,'state':'UNRECOGNIZED','sections':[]}
        if type(value) is dict:
            counts={};pending=[(value,0)];visited=0;unresolved=0;closures=[];truncated=False
            while pending:
                item,depth=pending.pop();visited+=1
                if visited>16384 or depth>24:truncated=True;break
                if type(item) is dict:
                    for key,child in item.items():
                        if type(key) is str and (key=='state' or key.endswith('_state') or key in ('status','source_closure')):
                            label=child if type(child) is str and child in allowed else 'UNRECOGNIZED'
                            counts[label]=counts.get(label,0)+1
                            if key=='source_closure':closures.append(label)
                        if key=='unresolved' and type(child) is list:unresolved+=len(child)
                        if type(child) in (dict,list):pending.append((child,depth+1))
                elif type(item) is list:
                    pending.extend((child,depth+1) for child in item if type(child) in (dict,list))
            row['recursive_status_counts']=[{'state':label,'record_count':count} for label,count in sorted(counts.items())]
            row['status_inventory_truncated']=truncated;row['unresolved_count']=unresolved
            row['source_closure_counts']=[{'state':label,'record_count':closures.count(label)} for label in sorted(set(closures))]
            state=value.get('state',value.get('ingredient_state'))
            row['state']=state if type(state) is str and state in allowed else 'UNRECOGNIZED'
            sections=value.get('sections',{})
            if type(sections) is dict and len(sections)<=64:
                for section_index,key in enumerate(sorted(sections,key=lambda x:str(type(x))+str(x))):
                    item=sections[key];state=item.get('state') if type(item) is dict else None
                    row['sections'].append({'section_index':section_index,'key_sha256':sha(canonical(key)),
                        'state':state if type(state) is str and state in allowed else 'UNRECOGNIZED'})
            else:row['sections_state']='INVALID_OR_OVERSIZE'
        result.append(row)
    return result

def case_summary(packet):
    result=packet['finite_probe']['result'];receipt=packet['probe_receipt'];cases=result['cases']
    need(result.get('failure') is None and result.get('incomplete_case') is None,'PROBE_COMPLETE')
    need(len(cases)==8 and len(result['server_observations'])==9 and len(receipt['events'])==129 and len(receipt['resources'])==35,'RECORD_COUNTS')
    cleanup=result['cleanup'];need(len(cleanup)==40 and cleanup==receipt['cleanup'],'CLEANUP_BINDING')
    removed=sum(x.get('status')=='REMOVED' for x in cleanup);stopped=sum(x.get('status')=='STOPPED_AND_EMPTY' for x in cleanup)
    need((removed,stopped)==(34,6),'CLEANUP_COUNTS')
    rows=[]
    for number,row in enumerate(cases,1):
        expected='FAIL_OBSERVED' if number in (6,8) else 'PASS_OBSERVED'
        need(row.get('case')==number and row.get('status')==expected,'CASE_STATUS')
        if number in (6,8):need(row.get('expected_rejection_observed') is True,'EXPECTED_REJECTION')
        rows.append({'case_index':number,'state':expected,'expected_rejection':number in (6,8),'record_sha256':sha(canonical(row))})
    return {'state':'SAVED_VALIDATORS_COMPLETED','case_count':8,'server_record_count':9,'event_count':129,'resource_count':35,
        'removed_count':removed,'stopped_and_empty_count':stopped,'cases':rows,'prior_failed_attempt':dict(PRIOR_HOLD)}

